    /* 출장품의서 링크 버튼 이벤트 */
    onBtnAply71Tap: function(button, e, eOpts) {
        var me = this,
            refs = me.getReferences(),
            vm = me.getViewModel(),
            cntView = me.getView(),
            docData = vm.get('docData'),
            aprHistId = docData.afterchange.comAprHistApfId, // 출장품의서 결재 이력 id
            record = {},						// 출장품의서 record 초기화
            command = '',						// 출장품의서 command 초기화
            aprViewId = 'HwmBtrAply71M';
        var data = {aprHistId :  aprHistId};

        // Service 호출
        Ext.Ajax.request({
            headers : {
                serviceId : 'COMAPR0001R04M',
                viewId : 'HwmBtrAply71M'
            },
            jsonData : data,
            scope : me,
            success : function(response, opts) {
                var me = this,
                    refs = me.getReferences(),
                    vm = me.getViewModel(),
                    command = Constants.sanction.COMPLETED_BOX, // 아무 동작도 하지 않아야 하므로 완료.
                    result = Ext.JSON.decode(Ext.JSON.decode(response.responseText).result), // 서버응답결과 JSON 변환
                    aprHistId = result.aprHistId,
                    docData = result.docData,
                    fieldValues = docData.fieldValues,
                    record = {
                        rgdt : fieldValues.rgdt.split(' ')[0], 	// 문서 제목
                        docNm : fieldValues.docNm,				// 출장품의서 데이터
                        viewOption : 'search'					// 출장품의서 닫기버튼만 남도록하는 플래그
                    };

                var win = Ext.create(aprViewId, {
                    command : command,
                    aprHistId : aprHistId,
                    docData : docData,
                    record : record
                });

                me.mon(win, 'complete', function(popup) {
                    popup.close(); //팝업창닫기
                }, me);


                win.show();
            },
            failure : function(response, opts){
                // Service 실패 했을 경우 기능
                Ext.Msg.show({
                    title : '실패',
                    message : '출장품의서를 가져오는데 문제가 발생했습니다.',
                    buttons : Ext.MessageBox.YES,
                    fn: function(btn){
                        if(btn === 'yes'){

                        }
                    }
                });
            }
        });

    },

    /* 첨부파일 다운로드 버튼 이벤트 */
    onBtnDownTap: function(button, e, eOpts) {
        var me = this,
            refs = me.getReferences(),
            atchFileId = refs.atchFileId.getValue();

        if (atchFileId) {
            var _url = Property.BASE_URL + Property.DOWN_URL + atchFileId;
            var form = document.createElement("form");
            form.setAttribute("method", "get");
            form.setAttribute("action", _url);
            form.setAttribute("target", "_blank");

            if(!Ext.os.is.Android) {
                // iOS일 경우 safari로 다운로드 처리
                window.open(_url, '_system');
            } else {
                document.body.appendChild(form);
                form.submit();
                document.body.removeChild(form);
            }
        }else{
            Ext.Msg.alert('첨부파일이 없습니다.');
        }
    },

