    Initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid; 		// 결재선 그리드

            var initialConfig = component.initialConfig,
            record = initialConfig.record, 					// 결재함 목록에서 선택한 레코드
            title = initialConfig.title,					// 문서제목
            docData = initialConfig.docData,				// 문서 총데이터
            aprHistId = initialConfig.aprHistId, 			// 결재내역 ID
            command = initialConfig.command,				// 결재 상태
            afterchange = docData.afterchange,				// 문서 폼 데이터
            gridScheduleInfoItems = initialConfig.gridScheduleInfo ? initialConfig.gridScheduleInfo.getStore().getData().items : docData.gridScheduleInfo, // 출장기간/장소 그리드 데이터
            atchFileId = afterchange.atchFileId,			// 첨부파일 ID
            atchFileNm = afterchange.atchFileNm,			// 첨부파일명
            atchFileParentId = afterchange.atchFileParentId,// 첨부파일 부모ID
            btrApfId = afterchange.hrWrkmBtrApfId;			// 출장품의서 ID


            /* 화면에서 필요한 데이터 */
            vm.set('docData', docData);
        vm.set('gridScheduleInfoItems', gridScheduleInfoItems);
        vm.set('afterchange', afterchange);
        vm.set('atchFileId', atchFileId);
        vm.set('atchFileNm', atchFileNm);
        vm.set('atchFileParentId', atchFileParentId);
        vm.set('btrApfId', btrApfId);
        /* 화면에서 필요한 데이터 */


        /* 결재에 필요한 데이터 */
        vm.set('aprHistId', aprHistId);
        vm.set('record', record);
        vm.set('command', command);
        /* 결재에 필요한 데이터 */


        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command   : command,
            viewModel : vm,
            aprHistId : aprHistId,
            edocCd    : 'HwmBtrRept71',
            scope     : me
        });

        this.initView();
    },

